class Solution:
    def __init__(self, font_properties, num_glyphs=10):

        self.font_properties = font_properties
        self.num_glyphs = num_glyphs

    def _get_glyph_count(self, text):
        glyph_count = 0
        for char in text:
            if char in 'abcdefghijklmnopqrstuvwxyz':
                glyph_count += 1
            elif char.isalpha():
                glyph_count += self._get_glyph_count(char)
        return glyph_count

    def _get_glyph_count(self, char):
        glyph_count = 0
        for i in range(ord(char) - self._get_glyph_offset_from_a, ord(char) - self._get_glyph_offset_from_b):
            glyph_count += 1
            if char[i] == 'a':
                glyph_count += self._get_glyph_count(chr(ord(char) + 1))
        return glyph_count

    def _get_glyph_offset_from_a(self, char):
        return ord(char) - self._get_glyph_offset_from_a

